  "description": "Transforms raw Excel data into structured compliance reports with automated risk detection, match extraction, and status mapping."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import * as XLSX from 'xlsx';

export interface ProcessConfig {
  highRiskKeywords: string[];
  aprvCodes: string[];
}

const getCellValue = (row: any[], index: number): string => {
  return row[index] !== undefined && row[index] !== null ? String(row[index]).trim() : '';
};

const extractValues = (text: string, key: string): string[] => {
  // Regex looks for key=value|
  // We assume the value cannot contain |
  // We make the | optional for the last item if the string ends abruptly, though user specified ends with |
  const regex = new RegExp(`${key}=([^|]+)\\|`, 'g');
  const matches: string[] = [];
  let match;
  while ((match = regex.exec(text)) !== null) {
    if (match[1]) {
      matches.push(match[1].trim());
    }
  }
  return matches;
};

export const processExcelFile = async (file: File, config: ProcessConfig): Promise<Uint8Array> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const data = e.target?.result;
        const workbook = XLSX.read(data, { type: 'array' });

        // Assume first sheet
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];

        // Convert to array of arrays (header: 1 means array of arrays)
        const jsonData: any[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1 });

        if (jsonData.length === 0) {
          throw new Error("Excel file is empty");
        }

        // Prepare new data structure
        // Header Row
        const newHeader = [
          "Status",           // A: Final Status
          "File name",        // B: Source C
          "Ref No",           // C: Source D
          "Customer Name",    // D: Source I
          "City",             // E: Source L
          "CTR",              // F: Source O
          "RPL 1",            // G: Match Name 1
          "RPL 2",            // H: Match Name 2
          "RPL 3",            // I: Match Name 3
          "RPL 4",            // J: Match Name 4
          "RPL 5",            // K: Match Name 5
          "Denial Type 1",    // L
          "Denial Type 2",    // M
          "Denial Type 3",    // N
          "Denial Type 4",    // O
          "Denial Type 5",    // P
        ];

        const processedRows = [newHeader];

        // Iterate rows, skipping header (index 0)
        for (let i = 1; i < jsonData.length; i++) {
          const rawRow = jsonData[i];
          if (!rawRow || rawRow.length === 0) continue;

          // Helper to get raw column by Excel index (0-based: A=0, B=1, C=2...)
          const rawC = getCellValue(rawRow, 2);  // File name
          const rawD = getCellValue(rawRow, 3);  // Ref No
          const rawI = getCellValue(rawRow, 8);  // Customer Name
          const rawJ = getCellValue(rawRow, 9);
          const rawK = getCellValue(rawRow, 10);
          const rawL = getCellValue(rawRow, 11); // City
          const rawO = getCellValue(rawRow, 14); // CTR
          const rawW = getCellValue(rawRow, 22);
          const rawAA = getCellValue(rawRow, 26);

          // --- Logic for Column A (Status) ---
          let status = "SPL"; // Default

          // Precompute flags
          const combinedSearchText = (rawW + " " + rawAA).toUpperCase();
          const hasZKWD = combinedSearchText.includes("ZKWD");
          const hasZEMB = combinedSearchText.includes("ZEMB");

          const isNoAdd = rawJ === "" && rawK === "" && rawL === "" && rawO === "";

          // Check High Risk Keywords (Case insensitive partial match in Customer Name)
          const isHighRisk = config.highRiskKeywords.some(kw => 
            kw && rawI.toLowerCase().includes(kw.toLowerCase())
          );

          // Check APRV (Exact match in CTR column rawO)
          // User listed codes: RU, UA, NI, VE, BY, CU, IR, KP, SY
          const isAPRV = config.aprvCodes.some(code => 
            code && rawO.toUpperCase() === code.toUpperCase()
          );

          // Apply Priority Logic
          // 1. High Risk overrides others? Or just "if matched".
          // We will apply a strict priority order based on typical compliance logic unless specified otherwise.
          // Order: High Risk > APRV > ZKWD/ZEMB > No Add > SPL

          if (isHighRisk) {
            status = "High Risk";
          } else if (isAPRV) {
            status = "APRV";
          } else if (hasZKWD || hasZEMB) {
             if (hasZKWD && hasZEMB) status = "ZKWD & ZEMB";
             else if (hasZKWD) status = "ZKWD";
             else status = "ZEMB";
          } else if (isNoAdd) {
            status = "No add";
          } else {
            status = "SPL";
          }

          // --- Logic for Data Extraction (Match Name / Denial Type) ---
          const textToSearch = (rawW + "|" + rawAA).replace(/\|+/g, '|'); // Normalize pipes just in case
          // Actually, raw concatenation might be safer:
          // The format is `key=value|`. Concatenating W and AA might merge `|` from W and start of AA.
          const rawCombined = rawW + " " + rawAA;

          const matchNames = extractValues(rawCombined, "matchname");
          const denialTypes = extractValues(rawCombined, "denialtype");

          // --- Construct Final Row ---
          const newRow = [
            status,             // A
            rawC,               // B
            rawD,               // C
            rawI,               // D
            rawL,               // E
            rawO,               // F
            matchNames[0] || "", // G
            matchNames[1] || "", // H
            matchNames[2] || "", // I
            matchNames[3] || "", // J
            matchNames[4] || "", // K
            denialTypes[0] || "", // L
            denialTypes[1] || "", // M
            denialTypes[2] || "", // N
            denialTypes[3] || "", // O
            denialTypes[4] || "", // P
          ];

          processedRows.push(newRow);
        }

        // Create new workbook
        const newWs = XLSX.utils.aoa_to_sheet(processedRows);
        const newWb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(newWb, newWs, "Processed Report");

        // Write to buffer
        const wbout = XLSX.write(newWb, { bookType: 'xlsx', type: 'array' });
        resolve(wbout);

      } catch (err) {
        reject(err);
      }
    };

    reader.onerror = (error) => reject(error);
    reader.readAsArrayBuffer(file);
  });
};

import React, { useState, KeyboardEvent } from 'react';
import { X, Plus } from 'lucide-react';

interface TagInputProps {
  tags: string[];
  onChange: (tags: string[]) => void;
  placeholder?: string;
  label?: string;
}

export const TagInput: React.FC<TagInputProps> = ({ tags, onChange, placeholder, label }) => {
  const [inputValue, setInputValue] = useState('');

  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      addTag();
    }
  };

  const addTag = () => {
    const trimmed = inputValue.trim();
    if (trimmed && !tags.includes(trimmed)) {
      onChange([...tags, trimmed]);
      setInputValue('');
    }
  };

  const removeTag = (tagToRemove: string) => {
    onChange(tags.filter(tag => tag !== tagToRemove));
  };

  return (
    <div className="w-full space-y-2">
      {label && <label className="block text-sm font-medium text-slate-700">{label}</label>}
      <div className="flex flex-wrap gap-2 p-2 border border-slate-300 rounded-lg bg-white min-h-[42px] focus-within:ring-2 focus-within:ring-indigo-500 focus-within:border-transparent transition-all">
        {tags.map((tag) => (
          <span key={tag} className="inline-flex items-center px-2.5 py-0.5 rounded-full text-sm font-medium bg-indigo-100 text-indigo-800">
            {tag}
            <button
              type="button"
              onClick={() => removeTag(tag)}
              className="ml-1.5 inline-flex items-center justify-center text-indigo-400 hover:text-indigo-600 focus:outline-none"
            >
              <X size={14} />
            </button>
          </span>
        ))}
        <input
          type="text"
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          onKeyDown={handleKeyDown}
          onBlur={addTag}
          className="flex-1 min-w-[120px] outline-none text-sm bg-transparent"
          placeholder={tags.length === 0 ? placeholder : ''}
        />
      </div>
      <p className="text-xs text-slate-500">Press Enter or click away to add.</p>
    </div>
  );
};

import React, { useState } from 'react';
import { Upload, FileSpreadsheet, AlertTriangle, Settings, CheckCircle, Download, FileText, Loader2 } from 'lucide-react';
import { processExcelFile } from './utils/excelProcessor';
import { TagInput } from './components/TagInput';

// Default values as requested
const DEFAULT_APRV_CODES = ['RU', 'UA', 'NI', 'VE', 'BY', 'CU', 'IR', 'KP', 'SY'];
const DEFAULT_RISK_KEYWORDS = ['SANCTION', 'EMBARGO', 'BLOCKED']; // User can add more via empty start

export default function App() {
  const [file, setFile] = useState<File | null>(null);
  const [processing, setProcessing] = useState(false);
  const [processedData, setProcessedData] = useState<Uint8Array | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Configuration State
  const [highRiskKeywords, setHighRiskKeywords] = useState<string[]>([]);
  const [aprvCodes, setAprvCodes] = useState<string[]>(DEFAULT_APRV_CODES);
  const [showSettings, setShowSettings] = useState(true);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
      setProcessedData(null);
      setError(null);
    }
  };

  const handleProcess = async () => {
    if (!file) return;

    setProcessing(true);
    setError(null);
    setProcessedData(null);

    try {
      // Small delay to allow UI to update to "Processing" state
      await new Promise(resolve => setTimeout(resolve, 500));

      const result = await processExcelFile(file, {
        highRiskKeywords,
        aprvCodes
      });
      setProcessedData(result);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "An unknown error occurred while processing the file.");
    } finally {
      setProcessing(false);
    }
  };

  const handleDownload = () => {
    if (!processedData) return;

    const blob = new Blob([processedData], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Processed_${file?.name || 'Report.xlsx'}`;
    document.body.appendChild(a);
    a.click();
    window.URL.revokeObjectURL(url);
    document.body.removeChild(a);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      {/* Sidebar / Configuration Panel */}
      <aside className={`bg-white border-r border-slate-200 w-full md:w-80 flex-shrink-0 transition-all duration-300 ease-in-out ${showSettings ? 'block' : 'hidden md:block'}`}>
        <div className="p-6 h-full overflow-y-auto">
          <div className="flex items-center gap-2 mb-8 text-indigo-600">
            <FileSpreadsheet className="w-8 h-8" />
            <h1 className="text-xl font-bold text-slate-900">Rule Processor</h1>
          </div>

          <div className="space-y-8">
            <section>
              <div className="flex items-center gap-2 mb-3 text-slate-800">
                <AlertTriangle className="w-4 h-4 text-amber-500" />
                <h2 className="font-semibold">High Risk Keywords</h2>
              </div>
              <p className="text-xs text-slate-500 mb-3">
                Rows with "Customer Name" matching these keywords will be marked as <strong>High Risk</strong>.
              </p>
              <TagInput 
                tags={highRiskKeywords} 
                onChange={setHighRiskKeywords} 
                label="" 
                placeholder="Add keyword (e.g., TERROR)" 
              />
            </section>

            <section>
              <div className="flex items-center gap-2 mb-3 text-slate-800">
                <CheckCircle className="w-4 h-4 text-emerald-500" />
                <h2 className="font-semibold">APRV Country Codes</h2>
              </div>
              <p className="text-xs text-slate-500 mb-3">
                Rows with "CTR" matching these codes will be marked as <strong>APRV</strong>.
              </p>
              <TagInput 
                tags={aprvCodes} 
                onChange={setAprvCodes} 
                label="" 
                placeholder="Add code (e.g., US)" 
              />
            </section>

             <section className="bg-slate-50 p-4 rounded-lg border border-slate-100">
              <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Logic Summary</h3>
              <ul className="text-xs text-slate-600 space-y-2 list-disc pl-4">
                <li><strong>No Add:</strong> If columns J, K, L, O are empty.</li>
                <li><strong>High Risk:</strong> Keyword match in Customer Name.</li>
                <li><strong>APRV:</strong> Country Code match in CTR.</li>
                <li><strong>ZKWD/ZEMB:</strong> Found in Raw columns W & AA.</li>
                <li><strong>SPL:</strong> Default if no conditions met.</li>
              </ul>
            </section>
          </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 p-6 md:p-12 flex flex-col items-center justify-center min-h-[calc(100vh-theme(spacing.20))]">
        <div className="w-full max-w-2xl">

          <div className="bg-white rounded-2xl shadow-xl border border-slate-100 overflow-hidden">
            {/* Header */}
            <div className="bg-indigo-600 p-8 text-center">
              <h2 className="text-2xl font-bold text-white mb-2">Process Compliance Report</h2>
              <p className="text-indigo-100">Upload your raw Excel log to generate the formatted output.</p>
            </div>

            {/* Body */}
            <div className="p-8 space-y-8">

              {/* Step 1: Upload */}
              <div className={`transition-all duration-300 ${processedData ? 'opacity-50 grayscale pointer-events-none' : 'opacity-100'}`}>
                <label 
                  htmlFor="file-upload" 
                  className={`
                    relative group flex flex-col items-center justify-center w-full h-48 rounded-xl border-2 border-dashed 
                    transition-all duration-200 cursor-pointer overflow-hidden
                    ${file 
                      ? 'border-indigo-400 bg-indigo-50' 
                      : 'border-slate-300 bg-slate-50 hover:bg-slate-100 hover:border-indigo-400'
                    }
                  `}
                >
                  <div className="flex flex-col items-center justify-center pt-5 pb-6">
                     {file ? (
                        <>
                          <FileText className="w-12 h-12 text-indigo-600 mb-3" />
                          <p className="text-sm font-medium text-indigo-900">{file.name}</p>
                          <p className="text-xs text-indigo-500 mt-1">{(file.size / 1024).toFixed(1)} KB</p>
                        </>
                     ) : (
                       <>
                          <Upload className="w-10 h-10 text-slate-400 mb-3 group-hover:text-indigo-500 transition-colors" />
                          <p className="mb-2 text-sm text-slate-500"><span className="font-semibold text-indigo-600">Click to upload</span> or drag and drop</p>
                          <p className="text-xs text-slate-400">XLSX, XLS files only</p>
                       </>
                     )}
                  </div>
                  <input id="file-upload" type="file" accept=".xlsx, .xls" className="hidden" onChange={handleFileChange} />
                </label>
              </div>

              {/* Action Buttons */}
              <div className="flex justify-center">
                {processing ? (
                  <button disabled className="flex items-center gap-2 px-8 py-3 bg-slate-100 text-slate-400 rounded-full font-semibold cursor-not-allowed">
                    <Loader2 className="w-5 h-5 animate-spin" />
                    Processing...
                  </button>
                ) : !processedData ? (
                  <button 
                    onClick={handleProcess} 
                    disabled={!file}
                    className={`
                      flex items-center gap-2 px-8 py-3 rounded-full font-semibold text-white shadow-lg transition-all transform hover:-translate-y-0.5
                      ${file ? 'bg-indigo-600 hover:bg-indigo-700 hover:shadow-indigo-500/30' : 'bg-slate-300 cursor-not-allowed'}
                    `}
                  >
                    <Settings className="w-4 h-4" />
                    Generate Report
                  </button>
                ) : (
                  <div className="flex flex-col items-center gap-4 animate-in fade-in slide-in-from-bottom-4 duration-500">
                    <div className="flex items-center gap-2 text-emerald-600 font-medium">
                      <CheckCircle className="w-5 h-5" />
                      Processing Complete
                    </div>
                    <div className="flex gap-3">
                       <button 
                        onClick={handleDownload}
                        className="flex items-center gap-2 px-8 py-3 bg-emerald-600 hover:bg-emerald-700 text-white rounded-full font-semibold shadow-lg shadow-emerald-500/30 transition-all transform hover:-translate-y-0.5"
                      >
                        <Download className="w-5 h-5" />
                        Download Result
                      </button>
                      <button 
                        onClick={() => {
                          setFile(null);
                          setProcessedData(null);
                        }}
                        className="flex items-center gap-2 px-4 py-3 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-full font-medium transition-colors"
                      >
                        Reset
                      </button>
                    </div>
                  </div>
                )}
              </div>

              {/* Error Message */}
              {error && (
                <div className="p-4 bg-red-50 border border-red-100 rounded-lg flex items-start gap-3 text-red-700 text-sm">
                  <AlertTriangle className="w-5 h-5 flex-shrink-0" />
                  <p>{error}</p>
                </div>
              )}
            </div>

          </div>

          <div className="mt-8 text-center text-slate-400 text-xs">
            <p>Processing happens locally in your browser. No data is uploaded to any server.</p>
          </div>
        </div>
      </main>
    </div>
  );
}

