import React, { useState, useEffect } from 'react';
import { Upload, FileSpreadsheet, AlertTriangle, Settings, CheckCircle, Download, FileText, Loader2 } from 'lucide-react';
import { processExcelFile } from './utils/excelProcessor';
import { TagInput } from './components/TagInput';

// Default values as requested
const DEFAULT_APRV_CODES = ['RU', 'UA', 'NI', 'VE', 'BY', 'CU', 'IR', 'KP', 'SY'];

export default function App() {
  const [file, setFile] = useState<File | null>(null);
  const [processing, setProcessing] = useState(false);
  const [processedData, setProcessedData] = useState<Uint8Array | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Configuration State with Persistence
  const [highRiskKeywords, setHighRiskKeywords] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('zyme_highRiskKeywords');
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      console.error('Failed to load high risk keywords from local storage', e);
      return [];
    }
  });

  const [aprvCodes, setAprvCodes] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('zyme_aprvCodes');
      return saved ? JSON.parse(saved) : DEFAULT_APRV_CODES;
    } catch (e) {
      console.error('Failed to load APRV codes from local storage', e);
      return DEFAULT_APRV_CODES;
    }
  });

  const [showSettings, setShowSettings] = useState(true);

  // Effects to save state changes to localStorage
  useEffect(() => {
    localStorage.setItem('zyme_highRiskKeywords', JSON.stringify(highRiskKeywords));
  }, [highRiskKeywords]);

  useEffect(() => {
    localStorage.setItem('zyme_aprvCodes', JSON.stringify(aprvCodes));
  }, [aprvCodes]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
      setProcessedData(null);
      setError(null);
    }
  };

  const handleProcess = async () => {
    if (!file) return;

    setProcessing(true);
    setError(null);
    setProcessedData(null);

    try {
      // Small delay to allow UI to update to "Processing" state
      await new Promise(resolve => setTimeout(resolve, 500));

      const result = await processExcelFile(file, {
        highRiskKeywords,
        aprvCodes
      });
      setProcessedData(result);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "An unknown error occurred while processing the file.");
    } finally {
      setProcessing(false);
    }
  };

  const handleDownload = () => {
    if (!processedData) return;

    const blob = new Blob([processedData], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Processed_${file?.name || 'Report.xlsx'}`;
    document.body.appendChild(a);
    a.click();
    window.URL.revokeObjectURL(url);
    document.body.removeChild(a);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      {/* Sidebar / Configuration Panel */}
      <aside className={`bg-white border-r border-slate-200 w-full md:w-80 flex-shrink-0 transition-all duration-300 ease-in-out ${showSettings ? 'block' : 'hidden md:block'}`}>
        <div className="p-6 h-full overflow-y-auto">
          <div className="flex items-center gap-2 mb-8 text-indigo-600">
            <FileSpreadsheet className="w-8 h-8" />
            <h1 className="text-xl font-bold text-slate-900">ZymeProcessor</h1>
          </div>

          <div className="space-y-8">
            <section>
              <div className="flex items-center gap-2 mb-3 text-slate-800">
                <AlertTriangle className="w-4 h-4 text-amber-500" />
                <h2 className="font-semibold">High Risk Keywords</h2>
              </div>
              <p className="text-xs text-slate-500 mb-3">
                Rows with "Customer Name" matching these keywords will be marked as <strong>High Risk</strong>.
              </p>
              <TagInput 
                tags={highRiskKeywords} 
                onChange={setHighRiskKeywords} 
                label="" 
                placeholder="Add keyword (e.g., TERROR)" 
              />
            </section>

            <section>
              <div className="flex items-center gap-2 mb-3 text-slate-800">
                <CheckCircle className="w-4 h-4 text-emerald-500" />
                <h2 className="font-semibold">APRV Country Codes</h2>
              </div>
              <p className="text-xs text-slate-500 mb-3">
                Rows with "CTR" matching these codes will be marked as <strong>APRV</strong>.
              </p>
              <TagInput 
                tags={aprvCodes} 
                onChange={setAprvCodes} 
                label="" 
                placeholder="Add code (e.g., US)" 
              />
            </section>
          </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 p-6 md:p-12 flex flex-col items-center justify-center min-h-[calc(100vh-theme(spacing.20))]">
        <div className="w-full max-w-2xl">

          <div className="bg-white rounded-2xl shadow-xl border border-slate-100 overflow-hidden">
            {/* Header */}
            <div className="bg-indigo-600 p-8 text-center">
              <h2 className="text-2xl font-bold text-white mb-2">Process Compliance Report</h2>
              <p className="text-indigo-100">Upload your raw Excel log to generate the formatted output.</p>
            </div>

            {/* Body */}
            <div className="p-8 space-y-8">

              {/* Step 1: Upload */}
              <div className={`transition-all duration-300 ${processedData ? 'opacity-50 grayscale pointer-events-none' : 'opacity-100'}`}>
                <label 
                  htmlFor="file-upload" 
                  className={`
                    relative group flex flex-col items-center justify-center w-full h-48 rounded-xl border-2 border-dashed 
                    transition-all duration-200 cursor-pointer overflow-hidden
                    ${file 
                      ? 'border-indigo-400 bg-indigo-50' 
                      : 'border-slate-300 bg-slate-50 hover:bg-slate-100 hover:border-indigo-400'
                    }
                  `}
                >
                  <div className="flex flex-col items-center justify-center pt-5 pb-6">
                     {file ? (
                        <>
                          <FileText className="w-12 h-12 text-indigo-600 mb-3" />
