                  <input id="file-upload" type="file" accept=".xlsx, .xls" className="hidden" onChange={handleFileChange} />
                </label>
              </div>

              {/* Action Buttons */}
              <div className="flex justify-center">
                {processing ? (
                  <button disabled className="flex items-center gap-2 px-8 py-3 bg-slate-100 text-slate-400 rounded-full font-semibold cursor-not-allowed">
                    <Loader2 className="w-5 h-5 animate-spin" />
                    Processing...
                  </button>
                ) : !processedData ? (
                  <button 
                    onClick={handleProcess} 
                    disabled={!file}
                    className={`
                      flex items-center gap-2 px-8 py-3 rounded-full font-semibold text-white shadow-lg transition-all transform hover:-translate-y-0.5
                      ${file ? 'bg-indigo-600 hover:bg-indigo-700 hover:shadow-indigo-500/30' : 'bg-slate-300 cursor-not-allowed'}
                    `}
                  >
                    <Settings className="w-4 h-4" />
                    Generate Report
                  </button>
                ) : (
                  <div className="flex flex-col items-center gap-4 animate-in fade-in slide-in-from-bottom-4 duration-500">
                    <div className="flex items-center gap-2 text-emerald-600 font-medium">
                      <CheckCircle className="w-5 h-5" />
                      Processing Complete
                    </div>
                    <div className="flex gap-3">
                       <button 
                        onClick={handleDownload}
                        className="flex items-center gap-2 px-8 py-3 bg-emerald-600 hover:bg-emerald-700 text-white rounded-full font-semibold shadow-lg shadow-emerald-500/30 transition-all transform hover:-translate-y-0.5"
                      >
                        <Download className="w-5 h-5" />
                        Download Result
                      </button>
                      <button 
                        onClick={() => {
                          setFile(null);
                          setProcessedData(null);
                        }}
                        className="flex items-center gap-2 px-4 py-3 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-full font-medium transition-colors"
                      >
                        Reset
                      </button>
                    </div>
                  </div>
                )}
              </div>

              {/* Error Message */}
              {error && (
                <div className="p-4 bg-red-50 border border-red-100 rounded-lg flex items-start gap-3 text-red-700 text-sm">
                  <AlertTriangle className="w-5 h-5 flex-shrink-0" />
                  <p>{error}</p>
                </div>
              )}
            </div>

          </div>

          <div className="mt-8 text-center text-slate-400 text-xs">
            <p>Processing happens locally in your browser. No data is uploaded to any server.</p>
          </div>
        </div>
      </main>
    </div>
  );
}

import React, { useState, KeyboardEvent } from 'react';
import { X } from 'lucide-react';

interface TagInputProps {
  tags: string[];
  onChange: (tags: string[]) => void;
  placeholder?: string;
  label?: string;
}

export const TagInput: React.FC<TagInputProps> = ({ tags, onChange, placeholder, label }) => {
  const [inputValue, setInputValue] = useState('');
  const [isFocused, setIsFocused] = useState(false);

  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      addTag();
    }
  };

  const addTag = () => {
    const trimmed = inputValue.trim();
    if (trimmed && !tags.includes(trimmed)) {
      onChange([...tags, trimmed]);
      setInputValue('');
    }
  };

  const removeTag = (tagToRemove: string) => {
    onChange(tags.filter(tag => tag !== tagToRemove));
  };

  return (
    <div className="w-full space-y-2">
      {label && <label className="block text-xs font-semibold text-slate-400 uppercase tracking-wider">{label}</label>}
      <div 
        className={`
          flex flex-wrap gap-2 p-2 border rounded-lg min-h-[46px] transition-all duration-200
          ${isFocused 
            ? 'bg-slate-800 border-indigo-500 ring-1 ring-indigo-500/50' 
            : 'bg-slate-800/50 border-slate-700 hover:border-slate-600'
          }
        `}
      >
        {tags.map((tag) => (
          <span key={tag} className="animate-in fade-in zoom-in duration-200 inline-flex items-center px-2.5 py-1 rounded-md text-sm font-medium bg-indigo-500/20 text-indigo-300 border border-indigo-500/30">
            {tag}
            <button
              type="button"
              onClick={() => removeTag(tag)}
              className="ml-1.5 inline-flex items-center justify-center text-indigo-400 hover:text-white transition-colors focus:outline-none"
            >
              <X size={14} />
            </button>
          </span>
        ))}
        <input
          type="text"
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          onKeyDown={handleKeyDown}
          onBlur={addTag}
          onFocus={() => setIsFocused(true)}
          onBlurCapture={() => setIsFocused(false)}
          className="flex-1 min-w-[120px] bg-transparent outline-none text-sm text-slate-200 placeholder-slate-500"
          placeholder={tags.length === 0 ? placeholder : ''}
        />
      </div>
      <p className="text-[10px] text-slate-500">Press Enter to add.</p>
    </div>
  );
};

